package app.vibefinancier;

import android.app.Activity;
import android.graphics.*;
import android.graphics.drawable.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.math.BigDecimal;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;

final class HistoryViews {
    interface Actions {void open(JSONObject p);void edit(JSONObject p);void trash(JSONObject p);void more();}
    static void list(Activity a,LinearLayout parent,HistoryData data,int limit,boolean debt,Actions actions){
        int shown=0;boolean limited=false;
        for(HistoryData.Day day:data.days){if(shown>=limit){limited=true;break;}LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.setPadding(Ui.dp(a,16),Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12));heading.setBackgroundColor(Appearance.mode(a).equals("oled")?0xff101010:Ui.SURFACE);TextView date=Ui.text(a,date(a,day.date),15,Ui.MUTED);heading.addView(date,new LinearLayout.LayoutParams(0,-2,1));TextView amount=Ui.rawText(a,amounts(a,day.amounts,true),15,Ui.INK);amount.setGravity(Gravity.END);amount.setTypeface(null,Typeface.BOLD);heading.addView(amount,new LinearLayout.LayoutParams(0,-2,1));parent.addView(heading);
            for(HistoryData.Row row:day.rows){if(shown++>=limit){limited=true;break;}View view=debt?debtRow(a,row,data):row(a,row,data);view.setTag("history.operation."+row.operation.optString("id"));view.setOnClickListener(v->actions.open(row.operation));parent.addView(new SwipeRow(a,view,()->actions.edit(row.operation),()->actions.trash(row.operation)),new LinearLayout.LayoutParams(-1,-2));View line=new View(a);line.setBackgroundColor(Ui.DIVIDER);parent.addView(line,new LinearLayout.LayoutParams(-1,Ui.dp(a,1)));}if(limited)break;
        }
        if(data.count==0){TextView empty=Ui.text(a,"No operations in this period.",16,Ui.MUTED);empty.setPadding(Ui.dp(a,16),Ui.dp(a,24),Ui.dp(a,16),Ui.dp(a,24));parent.addView(empty);}
        if(limited)parent.addView(Ui.button(a,"Load more operations",actions::more));
    }
    private static View row(Activity a,HistoryData.Row row,HistoryData data){
        JSONObject p=row.operation;LinearLayout line=new LinearLayout(a);line.setGravity(Gravity.CENTER_VERTICAL);line.setPadding(Ui.dp(a,16),Ui.dp(a,12),Ui.dp(a,14),Ui.dp(a,12));line.setMinimumHeight(Ui.dp(a,76));line.setBackgroundColor(Ui.CARD);
        JSONObject icon=!data.category.isEmpty()?data.entity(p.optString("account")):data.entity(p.optString("category"));if(!data.account.isEmpty()&&Set.of("transfer","debt").contains(p.optString("kind")))icon=counterparty(p,data);if(icon==null)icon=data.entity(p.optString("account"));line.addView(new CircleIcon(a,icon==null?"wallet":IconCatalog.resolve(icon),icon==null?0xff929a94:IconCatalog.color(icon)),new LinearLayout.LayoutParams(Ui.dp(a,38),Ui.dp(a,38)));
        LinearLayout text=new LinearLayout(a);text.setOrientation(LinearLayout.VERTICAL);text.setPadding(Ui.dp(a,12),0,Ui.dp(a,8),0);line.addView(text,new LinearLayout.LayoutParams(0,-2,1));text.addView(Ui.rawText(a,title(a,p,data),16,Ui.INK));String note=p.optString("note");if(!note.isEmpty())text.addView(Ui.rawText(a,note,12,Ui.MUTED));String stamp=p.optString("time");text.addView(Ui.rawText(a,Strings.t(a,kind(p))+(!stamp.isEmpty()?" · "+clock(stamp):""),11,Ui.MUTED));if(p.optJSONArray("unresolved")!=null&&p.optJSONArray("unresolved").length()>0)text.addView(Ui.text(a,"Unresolved source references",11,0xffd59b64));
        Map<String,BigDecimal> values=displayAmounts(row,data);TextView amount=Ui.rawText(a,amounts(a,values,true),17,negative(values)?0xffe36c6c:Ui.GREEN);amount.setGravity(Gravity.END);amount.setMaxLines(3);amount.setAutoSizeTextTypeUniformWithConfiguration(11,17,1,android.util.TypedValue.COMPLEX_UNIT_SP);line.addView(amount,new LinearLayout.LayoutParams(Ui.dp(a,120),-2));return line;
    }
    private static View debtRow(Activity a,HistoryData.Row row,HistoryData data){
        JSONObject p=row.operation;LinearLayout outer=new LinearLayout(a);outer.setPadding(Ui.dp(a,16),Ui.dp(a,10),Ui.dp(a,16),Ui.dp(a,10));LinearLayout card=new LinearLayout(a);GradientDrawable background=new GradientDrawable();background.setColor(Appearance.mode(a).equals("oled")?0xff111111:Ui.CARD);background.setCornerRadius(Ui.dp(a,12));card.setBackground(background);card.setClipToOutline(true);outer.addView(card,new LinearLayout.LayoutParams(-1,-2));JSONObject other=counterparty(p,data);int color=other==null?0xffffc84d:IconCatalog.color(other);
        LinearLayout side=Ui.column(a);side.setGravity(Gravity.CENTER);side.setPadding(Ui.dp(a,8),Ui.dp(a,14),Ui.dp(a,8),Ui.dp(a,14));side.setBackgroundColor(color);side.addView(new CircleIcon(a,other==null?"wallet":IconCatalog.resolve(other),color),new LinearLayout.LayoutParams(Ui.dp(a,44),Ui.dp(a,44)));TextView date=Ui.rawText(a,shortDate(a,p.optString("time")),13,0xff171b18);date.setGravity(Gravity.CENTER);side.addView(date);card.addView(side,new LinearLayout.LayoutParams(Ui.dp(a,94),-1));
        LinearLayout content=Ui.column(a);content.setPadding(Ui.dp(a,12),Ui.dp(a,10),Ui.dp(a,12),Ui.dp(a,12));content.addView(Ui.rawText(a,other==null?Strings.t(a,"Missing source reference"):other.optString("name"),17,Ui.INK));boolean positive=!negative(row.amounts);String kind=p.optString("kind"),label=kind.equals("opening")?"Opening balance":kind.equals("adjustment")?"Adjustment":positive?"To counterparty":"From counterparty";content.addView(Ui.text(a,label,13,positive?Ui.GREEN:0xffe36c6c));content.addView(Ui.rawText(a,amounts(a,row.amounts,true),20,positive?Ui.GREEN:0xffe36c6c));if(!p.optString("note").isEmpty())content.addView(Ui.rawText(a,p.optString("note"),12,Ui.MUTED));card.addView(content,new LinearLayout.LayoutParams(0,-2,1));return outer;
    }
    static View categoryCard(Activity a,JSONObject category,HistoryData data,Runnable edit){
        int color=IconCatalog.color(category),ink=0xff171b18;LinearLayout card=Ui.column(a);card.setPadding(Ui.dp(a,18),Ui.dp(a,16),Ui.dp(a,18),Ui.dp(a,18));GradientDrawable bg=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{color,Color.rgb((Color.red(color)+255)/2,(Color.green(color)+255)/2,(Color.blue(color)+255)/2)});bg.setCornerRadius(Ui.dp(a,16));card.setBackground(bg);LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(new CircleIcon(a,IconCatalog.resolve(category),color),new LinearLayout.LayoutParams(Ui.dp(a,48),Ui.dp(a,48)));TextView name=Ui.rawText(a,category.optString("name"),21,ink);name.setPadding(Ui.dp(a,12),0,0,0);heading.addView(name,new LinearLayout.LayoutParams(0,-2,1));Button button=Ui.button(a,"✎",edit);button.setContentDescription(Strings.t(a,"Edit category"));button.setTextColor(ink);button.setBackgroundColor(Color.TRANSPARENT);button.setMinWidth(0);heading.addView(button,new LinearLayout.LayoutParams(Ui.dp(a,48),Ui.dp(a,48)));card.addView(heading);
        String caption=data.hasIncome&&data.hasExpense?"Net movement":data.hasIncome?"Received":data.hasExpense?"Spent":category.optString("direction").equals("income")?"Received":"Spent";card.addView(Ui.text(a,caption,13,ink));BigDecimal total=data.hasIncome&&data.hasExpense?data.total:data.total.abs();TextView amount=Ui.rawText(a,money(a,total,data.base),34,ink);amount.setSingleLine(true);amount.setAutoSizeTextTypeUniformWithConfiguration(18,34,1,android.util.TypedValue.COMPLEX_UNIT_SP);card.addView(amount);if(data.missing>0)card.addView(Ui.text(a,"Incomplete valuation: "+data.missing,12,ink));if(data.hasFees)card.addView(Ui.text(a,"Fees included",12,ink));return card;
    }
    static JSONObject counterparty(JSONObject p,HistoryData data){String own=data.account;if(!own.isEmpty()){JSONArray legs=p.optJSONArray("postings");if(legs!=null)for(int i=0;i<legs.length();i++){JSONObject leg=legs.optJSONObject(i);if(leg!=null&&!leg.optString("account").equals(own)){JSONObject other=data.entity(leg.optString("account"));if(other!=null)return other;}}}return data.entity(p.optString("account"));}
    private static String title(Activity a,JSONObject p,HistoryData data){JSONObject category=data.entity(p.optString("category")),account=data.entity(p.optString("account"));String accountName=account==null?Strings.t(a,"Missing source reference"):account.optString("name");if(Set.of("debt","transfer").contains(p.optString("kind"))){JSONObject other=data.entity(p.optString("to"));return accountName+" → "+(other==null?Strings.t(a,"Missing source reference"):other.optString("name"));}if(category==null)return Strings.t(a,kind(p))+" · "+accountName;if(!data.category.isEmpty()&&p.optString("category").equals(data.category))return accountName;return category.optString("name")+" ("+accountName+")";}
    private static Map<String,BigDecimal> displayAmounts(HistoryData.Row row,HistoryData data){if(!data.account.isEmpty()||!data.category.isEmpty())return row.amounts;JSONObject p=row.operation;String kind=p.optString("kind");if(Set.of("transfer","debt").contains(kind)){Map<String,BigDecimal> amounts=new LinkedHashMap<>();BigDecimal sent=Money.decimal(p.optString("amount","0")).add(Money.decimal(p.optString("fee","0")));amounts.put(p.optString("currency"),sent.negate());String received=p.optString("received_currency");if(!received.isEmpty()&&!received.equals(p.optString("currency")))amounts.put(received,Money.decimal(p.optString("received_amount","0")));return amounts;}return row.amounts;}
    private static String kind(JSONObject p){return p.optString("kind").toUpperCase(Locale.ROOT);}
    private static boolean negative(Map<String,BigDecimal> values){for(BigDecimal amount:values.values())if(amount.signum()!=0)return amount.signum()<0;return false;}
    static String amounts(Activity a,Map<String,BigDecimal> values,boolean signed){StringJoiner text=new StringJoiner("\n");for(var entry:values.entrySet())text.add((signed&&entry.getValue().signum()>0?"+":"")+money(a,entry.getValue(),entry.getKey()));return text.length()==0?"—":text.toString();}
    static String money(Activity a,BigDecimal value,String currency){String text=Dashboard.format(value,currency);return Strings.russian(a)?text.replace('.',','):text;}
    private static String date(Activity a,String value){try{return LocalDate.parse(value).format(DateTimeFormatter.ofPattern("EEE, d MMMM yyyy",Strings.locale(a)));}catch(Exception e){return Strings.t(a,"Undated");}}
    private static String shortDate(Activity a,String value){try{return LocalDate.parse(value.substring(0,10)).format(DateTimeFormatter.ofPattern("dd\nMMM yyyy",Strings.locale(a)));}catch(Exception e){return Strings.t(a,"Undated");}}
    private static String clock(String value){try{return LocalDateTime.parse(value).format(DateTimeFormatter.ofPattern("HH:mm"));}catch(Exception e){return "";}}
}
